-- Slide hashes for duplicate detection on upload.html.
-- One column, plus a backfill for the posts that were added before the column existed.
-- Run once in the Supabase SQL editor. Re-runnable; nothing here removes anything.

alter table public.approval_uploads add column if not exists hashes text[];

